// -- HasFilters tests --

func TestConfig_HasFilters(t *testing.T) {
	t.Parallel()

	if (Config{}).HasFilters() {
		t.Error("empty config should not have filters")
	}
	if !(Config{Author: "alice"}).HasFilters() {
