// ACL post-filter: defence-in-depth
const accessibleFullNames = new Set(repos.map((r) => r.full_name))
let rows = rawRows.filter((row: any) => accessibleFullNames.has(`${row.org}/${row.repo}`))

// Apply author filter
if (params.author) {
  rows = rows.filter((row: any) => row.author_username === params.author)
}

// Apply date filter
if (params.date) {
  const threshold =
    params.date === "week"
      ? new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
      : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)
  rows = rows.filter((row: any) => {
    const created = row.created_at instanceof Date ? row.created_at : new Date(row.created_at)
    return created >= threshold
  })

  return results
}

private rowToCheckpointResult(row: any): CheckpointResult {
  return {
    id: row.checkpoint_id,
    prompt: row.prompt,
    commitMessage: row.commit_message ?? null,
    commitSha: row.commit_sha ?? null,
    branch: row.branch,
    org: row.org,
    repo: row.repo,
    author: row.author,
    authorUsername: row.author_username ?? null,
    createdAt: row.created_at instanceof Date ? row.created_at.toISOString() : row.created_at,
    filesTouched: Array.isArray(row.files_touched) ? row.files_touched : [],
  }
}

